INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='shaking-beef'), 1, 'Glossy dark cubes on a bed of greens, each sized for chopsticks.'),
((SELECT id FROM dishes WHERE slug='shaking-beef'), 2, 'Saigon cooks under French rule worked imported ingredients into it while keeping the wok.'),
((SELECT id FROM dishes WHERE slug='shaking-beef'), 3, 'It was once saved for wedding banquets and anniversaries, and now turns up on any weeknight.'),
((SELECT id FROM dishes WHERE slug='shaking-beef'), 4, 'You sear marinated beef cubes in a smoking wok, tossing the pan hard so they brown on all sides.'),
((SELECT id FROM dishes WHERE slug='shaking-beef'), 5, 'Peppery seared cubes on watercress and tomato, with a lime and salt dip, from Vietnam.'),
((SELECT id FROM dishes WHERE slug='bun-cha'), 1, 'Eaten off low plastic stools at lunchtime, beside a smoky sidewalk grill.'),
((SELECT id FROM dishes WHERE slug='bun-cha'), 2, 'One account credits a Hanoi grill master around 1900, and a writer in 1959 said the city was transfixed by it.'),
((SELECT id FROM dishes WHERE slug='bun-cha'), 3, 'A president and a TV chef ate it together in 2016, and the shop took the president''s name as a nickname.'),
((SELECT id FROM dishes WHERE slug='bun-cha'), 4, 'You grill pork patties and belly slices over charcoal, then drop them into a bowl of sweet, sour fish sauce.'),
((SELECT id FROM dishes WHERE slug='bun-cha'), 5, 'Smoky pork in a bowl of sweet-sour sauce, dipped up with cold rice noodles and herbs across Vietnam.'),
((SELECT id FROM dishes WHERE slug='banh-xeo'), 1, 'A huge yellow half-moon, crackling at the edges as you tear in.'),
((SELECT id FROM dishes WHERE slug='banh-xeo'), 2, 'It began as cheap street food for working people, and central and southern cooks both shaped it.'),
((SELECT id FROM dishes WHERE slug='banh-xeo'), 3, 'Mekong Delta cooks make it big and thin, while central cooks keep it small and dark with shrimp paste.'),
((SELECT id FROM dishes WHERE slug='banh-xeo'), 4, 'You pour turmeric rice batter into a smoking pan, add pork, shrimp and bean sprouts, and fold it once it crisps.'),
((SELECT id FROM dishes WHERE slug='banh-xeo'), 5, 'A crisp ''sizzling'' crepe torn up, wrapped in lettuce and dipped in fish sauce, from Vietnam.'),
((SELECT id FROM dishes WHERE slug='panang-curry'), 1, 'Thick rust-red sauce that clings to the meat instead of pooling.'),
((SELECT id FROM dishes WHERE slug='panang-curry'), 2, 'A cookbook printed in 1889 already lists a chicken version.'),
((SELECT id FROM dishes WHERE slug='panang-curry'), 3, 'It carries more coconut and fewer chilies than red curry, so it eats richer and gentler.'),
((SELECT id FROM dishes WHERE slug='panang-curry'), 4, 'You fry curry paste in coconut cream until the oil splits out, then add chicken and shredded lime leaves.'),
((SELECT id FROM dishes WHERE slug='panang-curry'), 5, 'Chicken in a rich Thai coconut curry, scattered with ground peanuts and slivered lime leaves.'),
((SELECT id FROM dishes WHERE slug='drunken-noodles'), 1, 'Wide, slippery noodles for late at night, hot enough to make you sweat.'),
((SELECT id FROM dishes WHERE slug='drunken-noodles'), 2, 'Cooks in Thailand built it from leftovers and pantry staples, an easy plate to fry after a long night.'),
((SELECT id FROM dishes WHERE slug='drunken-noodles'), 3, 'No alcohol goes in; one story says a wife loaded it with chili to cure her husband''s drinking.'),
((SELECT id FROM dishes WHERE slug='drunken-noodles'), 4, 'You stir-fry wide rice noodles with chicken, garlic, chilies and soy sauce, then toss in holy basil at the end.'),
((SELECT id FROM dishes WHERE slug='drunken-noodles'), 5, 'Thailand''s fiery late-night stir-fry of broad flat strands, glossy with dark soy and basil.'),
((SELECT id FROM dishes WHERE slug='larb'), 1, 'A plate you scoop up with your fingers, served neither hot nor cold.'),
((SELECT id FROM dishes WHERE slug='larb'), 2, 'Its name sounds like the word for luck, so families serve it at weddings and New Year.'),
((SELECT id FROM dishes WHERE slug='larb'), 3, 'Raw rice, toasted and pounded coarse, gives it a nutty crunch.'),
((SELECT id FROM dishes WHERE slug='larb'), 4, 'You toss cooked minced pork with lime juice, fish sauce, chili, shallots and lots of mint.'),
((SELECT id FROM dishes WHERE slug='larb'), 5, 'The national dish of Laos, a sour, herby minced-meat salad served with sticky rice and raw greens.'),
((SELECT id FROM dishes WHERE slug='ube-halaya'), 1, 'Bruise-purple jam spooned from a jar or set firm in a tin.'),
((SELECT id FROM dishes WHERE slug='ube-halaya'), 2, 'Cooks first sweetened it with coconut milk, and canned condensed milk took over later.'),
((SELECT id FROM dishes WHERE slug='ube-halaya'), 3, 'Boiled plain, the root tastes like any tuber; the flavour people know comes from cooking it down.'),
((SELECT id FROM dishes WHERE slug='ube-halaya'), 4, 'You mash boiled purple yam into melted butter and stir in sweetened milk until it sets stiff enough to slice.'),
((SELECT id FROM dishes WHERE slug='ube-halaya'), 5, 'The Philippines'' purple yam jam, chilled and sliced, or spooned onto halo-halo.'),
((SELECT id FROM dishes WHERE slug='sinigang'), 1, 'Broth so sour it makes you squint on the first spoonful.'),
((SELECT id FROM dishes WHERE slug='sinigang'), 2, 'Cooks sour it with tamarind, and also with guava, brought over on the Manila galleons.'),
((SELECT id FROM dishes WHERE slug='sinigang'), 3, 'A food-ranking website named it the world''s best soup in 2021.'),
((SELECT id FROM dishes WHERE slug='sinigang'), 4, 'You simmer pork ribs with tomato and tamarind, then add radish, okra, eggplant and water spinach.'),
((SELECT id FROM dishes WHERE slug='sinigang'), 5, 'Tamarind-sour pork soup crowded with greens, spooned over rice in Filipino homes.'),
((SELECT id FROM dishes WHERE slug='malai-kofta'), 1, 'Soft fried balls slipped into the sauce at the last minute so they hold.'),
((SELECT id FROM dishes WHERE slug='malai-kofta'), 2, 'Persian cooks gave the subcontinent its meatballs, and this meatless version swaps in paneer and potato.'),
((SELECT id FROM dishes WHERE slug='malai-kofta'), 3, 'The gravy gets its body from ground cashews and cream, and it is sweeter than most North Indian curries.'),
((SELECT id FROM dishes WHERE slug='malai-kofta'), 4, 'You mash paneer and potato into balls, fry them golden, and set them in a tomato, cashew and cream gravy.'),
((SELECT id FROM dishes WHERE slug='malai-kofta'), 5, 'India''s vegetarian ''cream dumplings'', fried paneer balls in a pale orange gravy.'),
((SELECT id FROM dishes WHERE slug='kheer'), 1, 'A sweet handed to worshippers as a temple offering.'),
((SELECT id FROM dishes WHERE slug='kheer'), 2, 'Food historian Achaya traced it to ancient Indian texts, where it was already popular.'),
((SELECT id FROM dishes WHERE slug='kheer'), 3, 'Nepal gives it a day of its own to mark the end of rice planting.'),
((SELECT id FROM dishes WHERE slug='kheer'), 4, 'You simmer rice slowly in milk, stirring as it goes, then sweeten it and add cardamom and saffron.'),
((SELECT id FROM dishes WHERE slug='kheer'), 5, 'Creamy rice pudding, pale gold with saffron and scattered with pistachios, served across India.'),
((SELECT id FROM dishes WHERE slug='keema'), 1, 'Spiced mince you scoop up with soft buttered rolls.'),
((SELECT id FROM dishes WHERE slug='keema'), 2, 'Its name travelled from Turkic through Persian, the same word Turks say as kıyma and Greeks as kimás.'),
((SELECT id FROM dishes WHERE slug='keema'), 3, 'Cooks stir in green peas for the version called matar, and Mumbai stalls serve it with buttered pav.'),
((SELECT id FROM dishes WHERE slug='keema'), 4, 'You brown minced lamb with onion, ginger and garlic, then cook it down with tomato and garam masala.'),
((SELECT id FROM dishes WHERE slug='keema'), 5, 'India''s spiced minced lamb, dry enough to scoop, with green peas and a squeeze of lime.'),
((SELECT id FROM dishes WHERE slug='chicken-karahi'), 1, 'Served sizzling in the heavy two-handled pan it cooked in.'),
((SELECT id FROM dishes WHERE slug='chicken-karahi'), 2, 'Lahore made the chicken version famous, and a lamb one is credited to the old North-West Frontier Province.'),
((SELECT id FROM dishes WHERE slug='chicken-karahi'), 3, 'Unlike most curries, it has no onion in the base, just tomatoes, ginger and garlic cooked down hard.'),
((SELECT id FROM dishes WHERE slug='chicken-karahi'), 4, 'You fry chicken in oil until browned, add chopped tomatoes, ginger, garlic and green chilies, and cook it dry.'),
((SELECT id FROM dishes WHERE slug='chicken-karahi'), 5, 'Pakistan''s wok-pan chicken, thick with tomato under ginger slivers, green chili and cilantro.'),
((SELECT id FROM dishes WHERE slug='seekh-kebab'), 1, 'Long cylinders of minced meat pulled off metal rods, smoking hot.'),
((SELECT id FROM dishes WHERE slug='seekh-kebab'), 2, 'Cooks in Pakistan, India and Bangladesh all grill it, in a tandoor or over a barbecue pit.'),
((SELECT id FROM dishes WHERE slug='seekh-kebab'), 3, 'Grillers send it out with raw onion slices, lemon and green mint chutney.'),
((SELECT id FROM dishes WHERE slug='seekh-kebab'), 4, 'You knead minced lamb with ginger, garlic, green chili and garam masala, mould it around skewers, and grill it.'),
((SELECT id FROM dishes WHERE slug='seekh-kebab'), 5, 'Pakistan''s skewered lamb mince, charred in long fingers and pulled off with naan.'),
((SELECT id FROM dishes WHERE slug='nihari'), 1, 'A slow stew eaten for breakfast, its meat soft enough to pull with bread.'),
((SELECT id FROM dishes WHERE slug='nihari'), 2, 'Delhi and Lucknow both claim it, and one tradition puts it in the royal kitchens of Awadh in the late 1700s.'),
((SELECT id FROM dishes WHERE slug='nihari'), 3, 'Some Old Delhi cooks stir yesterday''s leftover into the next pot, a trick they call taar.'),
((SELECT id FROM dishes WHERE slug='nihari'), 4, 'You slow-cook beef shank with marrow bones and warm spices, then thicken the gravy with toasted flour.'),
((SELECT id FROM dishes WHERE slug='nihari'), 5, 'Slow-braised beef shank in glossy red gravy under ginger and green chili, served across Pakistan.'),
((SELECT id FROM dishes WHERE slug='kebab-koobideh'), 1, 'Two long strips of minced meat laid over a mound of buttered rice.'),
((SELECT id FROM dishes WHERE slug='kebab-koobideh'), 2, 'Cooks pounded the meat by hand before grinders, and now run it through twice.'),
((SELECT id FROM dishes WHERE slug='kebab-koobideh'), 3, 'Grillers press finger grooves into the meat on wide flat skewers and turn it constantly over fierce coals.'),
((SELECT id FROM dishes WHERE slug='kebab-koobideh'), 4, 'You mix ground lamb with grated, squeezed onion, salt and pepper, then pack it onto skewers by hand.'),
((SELECT id FROM dishes WHERE slug='kebab-koobideh'), 5, 'Charred minced lamb over buttered rice with grilled tomato and sumac, from Iranian grill houses.'),
((SELECT id FROM dishes WHERE slug='halloumi'), 1, 'Slabs of white cheese that go golden in a dry pan instead of melting.'),
((SELECT id FROM dishes WHERE slug='halloumi'), 2, 'The name traces to a cheese eaten in medieval Egypt, and a folk account of making it dates to Byzantine times.'),
((SELECT id FROM dishes WHERE slug='halloumi'), 3, 'It squeaks against your teeth, a trick of the milk protein, and flecks of mint run through it.'),
((SELECT id FROM dishes WHERE slug='halloumi'), 4, 'You slice the brined cheese thick and sear it hard on both sides, then finish it with lemon.'),
((SELECT id FROM dishes WHERE slug='halloumi'), 5, 'Salty goat and sheep milk cheese built for the grill, its name protected by the EU for Cyprus alone.'),
((SELECT id FROM dishes WHERE slug='shish-kebab'), 1, 'Cubes of meat threaded on a long blade and turned over glowing coals.'),
((SELECT id FROM dishes WHERE slug='shish-kebab'), 2, 'Its name is Old Turkic, and lamb is the meat cooks in Türkiye have traditionally threaded on.'),
((SELECT id FROM dishes WHERE slug='shish-kebab'), 3, 'Restaurants plate it with pilaf, a charred tomato half and raw onion dusted red with sumac.'),
((SELECT id FROM dishes WHERE slug='shish-kebab'), 4, 'You cube lamb, marinate it, thread it on skewers between onion and pepper, and grill it over charcoal.'),
((SELECT id FROM dishes WHERE slug='shish-kebab'), 5, 'Türkiye''s skewered lamb cubes, blistered over coals and slid onto pilaf beside grilled peppers.');
